-- Prompt 10 sections 7, 8 and 10. FDP trainings over several days (times per day, what the university provides, HOD-approved
-- nominations, attendance per day, certificates); AI checks (per-institute models, monthly budget, usage log with tokens
-- and cost, results cached per version); visiting pay (faculty category and filer status, hourly rate card per term,
-- late and tax rules, pay period, biometric column mapping, pay sheets the HOD approves and Accounts marks paid).
-- Side tables only; safe to run more than once.
CREATE TABLE IF NOT EXISTS "FdpSessionPlan" ("sessionId" TEXT PRIMARY KEY, "planJson" TEXT NOT NULL DEFAULT '{}', "updatedById" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "FdpNomination" ("id" TEXT PRIMARY KEY, "sessionId" TEXT NOT NULL, "userId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "nominatedById" TEXT NOT NULL, "decidedById" TEXT, "decidedAt" TIMESTAMP(3), "reason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "FdpNomination_session_idx" ON "FdpNomination"("sessionId");
CREATE TABLE IF NOT EXISTS "FdpDayAttendance" ("id" TEXT PRIMARY KEY, "sessionId" TEXT NOT NULL, "userId" TEXT NOT NULL, "date" TEXT NOT NULL, "markedById" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "FdpDayAttendance_session_idx" ON "FdpDayAttendance"("sessionId");
CREATE TABLE IF NOT EXISTS "FdpCertificate" ("id" TEXT PRIMARY KEY, "sessionId" TEXT NOT NULL, "userId" TEXT NOT NULL, "fileName" TEXT NOT NULL DEFAULT '', "fileRef" TEXT NOT NULL, "uploadedById" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "FdpCertificate_session_idx" ON "FdpCertificate"("sessionId");
CREATE TABLE IF NOT EXISTS "AiCheckSetting" ("chairmanId" TEXT PRIMARY KEY, "enabled" BOOLEAN NOT NULL DEFAULT true, "monthlyBudgetUsd" DOUBLE PRECISION NOT NULL DEFAULT 20, "paperModel" TEXT NOT NULL DEFAULT 'claude-haiku-5-5', "planModel" TEXT NOT NULL DEFAULT 'claude-opus-5-5', "pricesJson" TEXT NOT NULL DEFAULT '{}', "updatedById" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "AiUsage" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "userId" TEXT NOT NULL, "kind" TEXT NOT NULL, "courseId" TEXT, "versionKey" TEXT, "model" TEXT NOT NULL, "inputTokens" INTEGER NOT NULL DEFAULT 0, "outputTokens" INTEGER NOT NULL DEFAULT 0, "costUsd" DOUBLE PRECISION NOT NULL DEFAULT 0, "cached" BOOLEAN NOT NULL DEFAULT false, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "AiUsage_month_idx" ON "AiUsage"("chairmanId", "createdAt");
CREATE TABLE IF NOT EXISTS "AiCheckCache" ("key" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "kind" TEXT NOT NULL, "courseId" TEXT, "resultJson" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "VisitingPayProfile" ("userId" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "category" TEXT, "ratePerHour" DOUBLE PRECISION, "filer" BOOLEAN NOT NULL DEFAULT true, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "VisitingRateCard" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "termLabel" TEXT NOT NULL, "category" TEXT NOT NULL, "ratePerHour" DOUBLE PRECISION NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "VisitingRateCard_key" ON "VisitingRateCard"("chairmanId", "termLabel", "category");
CREATE TABLE IF NOT EXISTS "VisitingPaySetting" ("chairmanId" TEXT PRIMARY KEY, "lateMode" TEXT NOT NULL DEFAULT 'PCT', "lateFixed" DOUBLE PRECISION NOT NULL DEFAULT 0, "lateEveryN" INTEGER NOT NULL DEFAULT 3, "periodWeeks" INTEGER NOT NULL DEFAULT 4, "taxJson" TEXT NOT NULL DEFAULT '{"mode":"PCT","filerPct":10,"nonFilerPct":20,"slabs":[]}', "biometricMapJson" TEXT NOT NULL DEFAULT '{}', "updatedById" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "VisitingPaySheet" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "userId" TEXT NOT NULL, "periodStart" TIMESTAMP(3) NOT NULL, "periodEnd" TIMESTAMP(3) NOT NULL, "claimIdsJson" TEXT NOT NULL DEFAULT '[]', "linesJson" TEXT NOT NULL DEFAULT '[]', "hours" DOUBLE PRECISION NOT NULL DEFAULT 0, "rate" DOUBLE PRECISION NOT NULL DEFAULT 0, "gross" DOUBLE PRECISION NOT NULL DEFAULT 0, "deductions" DOUBLE PRECISION NOT NULL DEFAULT 0, "bonus" DOUBLE PRECISION NOT NULL DEFAULT 0, "tax" DOUBLE PRECISION NOT NULL DEFAULT 0, "net" DOUBLE PRECISION NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'DRAFT', "hodId" TEXT, "hodAt" TIMESTAMP(3), "paidRef" TEXT, "paidAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "VisitingPaySheet_user_idx" ON "VisitingPaySheet"("userId", "periodStart");
